DOCS=[
('getting-started','Start here','Choose the right route','An introduction to DeskRally, the two connection types, and what you need before a session.'),
('receiving-support','Receiving support','Get help with your computer','What to expect when a technician asks you to join a one-time support session.'),
('technician-guide','Technician guide','Connect and work','A practical guide to the browser console, session controls, and finishing a support session.'),
('self-hosting','Self-hosting','Understand the moving parts','A plain-language map of the console, agents, server, database, and relay.'),
('security','Security & consent','Keep access deliberate','Set boundaries for remote access, protect credentials, and keep support sessions intentional.')]
PAGES={}
def page(path,title,desc,body,kind='standard'):PAGES[path]={'title':title,'description':desc,'body':body,'kind':kind}
def arrow():return '<span aria-hidden="true">↗</span>'
def card(slug,title,desc,tag='Guide'):
 return f'<a class="doc-card" href="/docs/{slug}/"><span class="eyebrow">{tag}</span><h3>{title} {arrow()}</h3><p>{desc}</p></a>'
page('/','A clearer route to remote support','DeskRally is a Windows-first remote support and unattended access project, with a browser console and self-hosted infrastructure.',f'''
<section class="hero wrap">
 <div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> Windows-first · Self-hosted</p>
 <h1>Remote support.<br><span>A clearer route.</span></h1>
 <p class="hero-lede">Help someone get back to their day. Connect to the computers you manage. Keep the route on infrastructure you control.</p>
 <div class="actions"><a class="button primary" href="/docs/getting-started/">Find your starting point <span aria-hidden="true">→</span></a><a class="text-link" href="/about/">Meet DeskRally {arrow()}</a></div>
 <p class="hero-note">A practical project for remote support and unattended access.</p></div>
 <div class="route-poster" aria-label="Illustration of a winding rally route"><div class="poster-top"><span>DESKRALLY / ROADBOOK</span><span aria-hidden="true">N ↑</span></div><img src="/assets/rally-route.svg" width="800" height="520" alt="A winding road through contour lines, with a route marker and checkered flag."><div class="poster-bottom"><span class="checkers" aria-hidden="true"></span><span>Good support keeps you moving.</span><span aria-hidden="true">01 / DR</span></div></div>
</section>
<div class="route-strip"><div class="wrap route-strip-inner"><span><b>01</b> Windows agents</span><span><b>02</b> Browser console</span><span><b>03</b> Your infrastructure</span></div></div>
<section class="wrap section" id="overview"><div class="section-intro"><p class="eyebrow">The overview</p><h2>One project.<br>Two ways to connect.</h2><p>Different support jobs need different starting points. DeskRally brings one-time help and access to managed computers into the same console.</p></div>
 <div class="connection-grid"><article class="connection-card"><div class="card-top"><span class="route-number">01</span><span class="small-label">Someone needs a hand</span></div><h3>Remote support</h3><p>A technician shares a session code. The person receiving help opens the support client and approves screen sharing when they are ready.</p><a href="/docs/receiving-support/">How a support session works {arrow()}</a></article>
 <article class="connection-card dark-card"><div class="card-top"><span class="route-number">02</span><span class="small-label">A computer you manage</span></div><h3>Unattended access</h3><p>An installed agent makes a managed computer available to authorized technicians, without a person having to enter a code for each session.</p><a href="/docs/technician-guide/">Explore the technician workflow {arrow()}</a></article></div>
</section>
<section class="workbench"><div class="wrap workbench-grid"><div><p class="eyebrow">Behind the wheel</p><h2>A browser console.<br>A place to get things done.</h2><p>Find a machine, start a session, and work with the tools your account is allowed to use. Remote screen control and background tools support different kinds of troubleshooting.</p><a class="text-link" href="/docs/technician-guide/">Read the technician guide {arrow()}</a></div>
 <div class="console-demo" aria-label="Illustrative console, not a live connection"><div class="demo-toolbar"><span class="demo-dots" aria-hidden="true">● ● ●</span><span>DeskRally / Console</span><span class="demo-label">Illustration</span></div><div class="demo-body"><div class="demo-sidebar"><span class="eyebrow">Machines</span><div class="demo-machine active"><i aria-hidden="true"></i> Workshop PC <span>Windows</span></div><div class="demo-machine"><i aria-hidden="true"></i> Office desktop <span>Windows</span></div><div class="demo-machine"><i class="offline" aria-hidden="true"></i> Spare laptop <span>Offline</span></div></div><div class="demo-stage"><div class="route-cross" aria-hidden="true">↗</div><strong>Ready when you are.</strong><span>Select a machine to begin.</span></div></div><div class="demo-footer">Illustrative view · No real machines or account data</div></div></div>
</section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">The roadbook</p><h2>A useful place to start.</h2></div><a class="text-link" href="/docs/">All documentation {arrow()}</a></div><div class="guide-grid">{card('receiving-support','Here for help?','Know what to expect before you share your screen.','For support guests')}{card('technician-guide','Supporting a computer?','Find your way around a session and its controls.','For technicians')}{card('self-hosting','Running your own setup?','Understand the components and plan your deployment.','For self-hosters')}</div></section>
<section class="source-band"><div class="wrap source-band-inner"><div><p class="eyebrow">Follow the project</p><h2>The next checkpoint: public source.</h2><p>The public source release is being prepared. Documentation is available now; a GitHub link will be added when the repository is ready.</p></div><a class="button paper" href="/source/">Source release status {arrow()}</a></div></section>
''','home')
page('/docs/','Documentation','DeskRally documentation for support guests, technicians, and self-hosters.','''<section class="wrap page-head"><p class="eyebrow">The roadbook</p><h1>Find your route.</h1><p>Practical guides for getting help, supporting computers, and understanding your own deployment.</p></section><section class="wrap docs-library"><label class="search-label" for="docs-search">Search the guides</label><div class="search-field"><span aria-hidden="true">⌕</span><input id="docs-search" type="search" placeholder="Try ‘session code’, ‘Windows’, or ‘hosting’" autocomplete="off" aria-controls="guide-results"></div><p class="search-count" id="search-count" role="status" aria-live="polite">Five guides to get you started.</p><div class="guide-grid" id="guide-results">'''+''.join(card(slug,title,desc,label) for slug,label,title,desc in DOCS)+'''</div><p id="search-empty" hidden>No guides found. Try a broader term, such as “support” or “access”.</p><noscript><p>Search needs JavaScript. All guides are listed above and work without it.</p></noscript></section>''')
CONTENT={
'getting-started':('Start here','A good session starts with the right route.', '''<p>DeskRally is a Windows-first project for remote support and unattended access. Technicians use a browser console to connect to Windows computers running a DeskRally agent. A deployment has its own server address and accounts.</p><div class="note"><strong>Looking for help right now?</strong><p>This is the project website, not a public help desk. Use the address and instructions supplied by a technician you contacted for help.</p></div><h2 id="choose">Choose your starting point</h2><ul><li><strong>I need help with my computer.</strong> Start with <a href="/docs/receiving-support/">receiving support</a>. You do not need a technician account to join a one-time support session.</li><li><strong>I support other computers.</strong> Read the <a href="/docs/technician-guide/">technician guide</a>. You need an account on your organization’s deployment and permission to access the target computer.</li><li><strong>I want to run DeskRally.</strong> Read the <a href="/docs/self-hosting/">self-hosting overview</a> to understand the components and operating responsibilities.</li></ul><h2 id="connection-types">Understand the two connection types</h2><h3>One-time support</h3><p>A technician creates a support session and shares a code or support link. The person receiving help runs the support client and approves sharing on the computer that needs help. Entering a session code does not itself approve screen sharing.</p><h3>Unattended access</h3><p>An administrator installs an agent on a computer that will be managed over time. Authorized technicians can then connect under that deployment’s account permissions and policies.</p><h2 id="prepare">Before you connect</h2><ul><li>Know which computer needs help and which deployment you are using.</li><li>Check that the computer has an internet connection.</li><li>Close sensitive windows before sharing your screen.</li><li>Use software and instructions supplied by the administrator of your deployment.</li></ul><h2 id="availability">Source and download availability</h2><p>The public source repository and versioned distribution are being prepared. This site does not currently offer a public installer or a hosted support account. Check <a href="/source/">source release status</a> for the current position.</p>'''),
'receiving-support':('Receiving support','Get help. Stay in the loop.', '''<p>A one-time support session lets a technician help with a Windows computer while you are there. Your technician supplies the support address and session code for their deployment.</p><div class="note caution"><strong>Start with someone you meant to contact.</strong><p>Only follow these steps if you asked for help using contact details you independently trust. An unexpected caller directing you to remote-access software is a reason to stop.</p></div><h2 id="contact">1. Contact your technician</h2><p>Explain the issue and confirm which computer needs help. Ask for the support address and a session code or support link. Keep the code private; do not post it in a public issue or chat.</p><h2 id="client">2. Open the support client</h2><p>Use the download or session bundle supplied by your technician’s deployment. Run it on the computer that needs help. If Windows or the browser shows a warning, stop and read the exact warning to your technician. Do not assume a warning is safe to bypass.</p><h2 id="code">3. Enter the session code</h2><p>Enter the code from your technician, or follow the support link they gave you. If it has expired or is rejected, ask for a new one. Typing a code prepares the session; it does not grant screen-sharing consent.</p><h2 id="consent">4. Approve when you are ready</h2><p>Check the support address in the permission prompt. Close anything you do not want visible. Approve sharing and control only when you are ready. The client shows a support indicator during the session.</p><h2 id="finish">5. End the session</h2><p>You can end the session from the support client. Tell your technician when you are finished, and close the client. A one-time support session and a permanently installed agent are different: ask your technician if you are unsure which you have been given.</p><h2 id="troubleshooting">If something does not work</h2><ul><li><strong>Code not accepted:</strong> ask the technician to check the code and whether the session is still available.</li><li><strong>Download blocked:</strong> share the warning with your technician rather than turning off protection.</li><li><strong>No connection:</strong> check your internet connection and confirm the deployment address with your technician.</li><li><strong>Unexpected behavior:</strong> end the session and contact the technician through a known channel.</li></ul>'''),
 'technician-guide':('Technician guide','A clear route through a support session.', '''<p>The browser console is the starting point for managing machines and support sessions. Available controls depend on your role, deployment policy, and the agent’s capabilities.</p><h2 id="sign-in">Sign in to your deployment</h2><p>Open the console address supplied by your administrator. Check the organization field, then sign in using the account method configured for your deployment. If your account has a verification code requirement, complete it as part of sign-in.</p><h2 id="pick-route">Choose the connection type</h2><ul><li><strong>Managed computer:</strong> select a machine your account is allowed to access and start a connection.</li><li><strong>One-time support:</strong> create an attended session, then share its support link or code directly with the person who requested help.</li></ul><p>Do not publish session codes, support bundles, account details, or deployment tokens in public issues.</p><h2 id="tools">Use the tools the job needs</h2><p>Once connected, the session toolbar provides screen and input controls. Other tools can include file access, system information, and background administration, subject to permissions and agent support.</p><p>Explain significant actions to the person receiving help. Elevation, file changes, and background tools can affect the remote computer even when they do not look like ordinary mouse-and-keyboard activity.</p><h2 id="reconnect">When a session is interrupted</h2><p>Check the console’s connection status before trying another action. If the machine or client has restarted, allow it to become available again. Avoid starting duplicate sessions while you are still determining whether the first connection is active.</p><h2 id="close">Finish deliberately</h2><ol><li>Confirm that the person receiving help knows what changed.</li><li>Stop any commands or transfers that should not continue.</li><li>Disconnect and confirm the session has ended.</li><li>Sign out of the console when you are finished on a shared computer.</li></ol><h2 id="permissions">If a control is unavailable</h2><p>A missing or disabled control may reflect account permissions, a deployment policy, a disconnected agent, or a platform limitation. Ask your deployment administrator; do not work around an access restriction by sharing another person’s credentials.</p>'''),
 'self-hosting':('Self-hosting','Your infrastructure. A map of the moving parts.', '''<p>DeskRally separates the browser interface, connection services, and Windows agents. Operating it means maintaining both the application and the systems that carry remote sessions.</p><div class="note"><strong>Release preparation</strong><p>The public source distribution is still being prepared. This page explains the architecture and deployment planning. Versioned build and installation commands will be published alongside that release.</p></div><h2 id="architecture">The components</h2><div class="architecture" aria-label="Connection architecture"><div>Browser console<span>Technician interface</span></div><b aria-hidden="true">↕</b><div>Control plane & signaling<span>Accounts, permissions, session setup</span></div><b aria-hidden="true">↕</b><div>Windows agent<span>Screen sharing and remote tools</span></div><p>WebRTC carries session media; relay infrastructure supports connections where a direct route is unavailable.</p></div><dl><dt>Web console</dt><dd>A browser interface built with React and TypeScript.</dd><dt>Control plane and connection services</dt><dd>Go services handle the API, signaling, and relay responsibilities.</dd><dt>Windows agent</dt><dd>Rust components handle the remote computer side of a session.</dd><dt>Database</dt><dd>PostgreSQL stores application records. Keep it private to the deployment.</dd><dt>STUN/TURN</dt><dd>Network traversal services help sessions connect across different networks. Plan relay capacity as part of the deployment.</dd></dl><h2 id="plan">Plan before you deploy</h2><ul><li>A server environment for the application services and database.</li><li>A domain and HTTPS certificates for browser access.</li><li>A reachable STUN/TURN configuration and appropriate network rules.</li><li>Windows computers for agents, with the permissions required for installation.</li><li>A plan for upgrades, database backups, monitoring, and credential recovery.</li></ul><h2 id="boundaries">Keep the boundaries clear</h2><p>A public project website is separate from a deployment’s authenticated console. Do not expose database ports or internal service listeners as public websites. Use deployment-specific credentials and keep private signing material outside source control.</p><h2 id="responsibility">What a self-hoster operates</h2><p>The deployment administrator is responsible for accounts, access policy, agent rollout, network configuration, backups, and updates. Start with a small test environment and verify both connection behavior and access boundaries before relying on it for other people’s computers.</p>'''),
 'security':('Security & consent','Keep remote access deliberate.', '''<p>Remote access can display information and change a computer. Treat permission, identity, and the way sessions end as part of the workflow—not as background details.</p><h2 id="guests">For the person receiving help</h2><ul><li>Start with a technician you intended to contact.</li><li>Confirm the deployment address and read client permission prompts.</li><li>Close sensitive material before sharing your screen.</li><li>End the session if anything is unexpected.</li></ul><h2 id="operators">For technicians and administrators</h2><ul><li>Give each person their own account and only the access they need.</li><li>Use HTTPS and protect administrative credentials and verification factors.</li><li>Review which computers have a permanent agent installed.</li><li>Keep agent, server, operating-system, and database updates part of normal maintenance.</li><li>Protect logs and audit records; they may contain sensitive operational information.</li></ul><h2 id="public-information">What should stay out of public source</h2><p>Passwords, enrollment tokens, private signing keys, session codes, private account records, personal screenshots, and raw operational logs do not belong in a public repository or issue. Use generic examples rather than real deployment details.</p><h2 id="issues">Reporting a concern</h2><p>Private security-reporting instructions will accompany the public repository. Until those instructions are available, do not publish exploit details that expose a real deployment or anyone’s credentials. For an issue on a deployment you use, contact its administrator through your established private channel.</p><h2 id="scope">Understand the limits</h2><p>This site describes intended workflows and operating practices. It is not a security certification. A deployment’s security also depends on its version, configuration, infrastructure, and administration.</p>''')}
for slug,(title,subtitle,body) in CONTENT.items():
 page('/docs/'+slug+'/',title,next(d[3] for d in DOCS if d[0]==slug),f'<p class="eyebrow">The roadbook / {title}</p><h1>{title}</h1><p class="article-lede">{subtitle}</p>'+body,'doc')
page('/about/','About DeskRally','Meet DeskRally, a Windows-first remote support and unattended access project.','''<section class="wrap page-head"><p class="eyebrow">About the project</p><h1>Good support<br>keeps people moving.</h1><p>DeskRally is a practical project for helping with computers, whether someone is there to ask for a hand or a managed machine needs attention.</p></section><section class="wrap about-grid section"><div><h2>Why the rally?</h2><p>A rally is about finding a route, reading the conditions, and working together to get to the next checkpoint. That is the idea behind DeskRally: useful tools and a clear way through the job.</p><p>The road theme is a reminder to keep things understandable. The support workflow still uses plain terms: sign in, join a session, share a screen, disconnect.</p></div><div class="about-sign"><span class="eyebrow">The direction</span><h2>Clear routes.<br>Useful tools.<br>Deliberate access.</h2><span class="checkers" aria-hidden="true"></span></div></section><section class="wrap narrow section"><h2>What DeskRally is</h2><p>A Windows-first remote support and unattended access project with a browser-based console and self-hosted services. Its source includes Rust, Go, and TypeScript components.</p><h2>What this website is for</h2><p>This is the public project home and documentation. It introduces the software and explains the workflows. It does not provide a public support service, issue technician accounts, or collect session codes.</p><h2>A project taking shape</h2><p>The public source release is being prepared. The <a href="/source/">source page</a> explains the current availability, and the <a href="/docs/">roadbook</a> is the starting point for documentation.</p></section>''')
page('/source/','Source release','Status of the DeskRally public source release and GitHub repository.','''<section class="wrap page-head"><p class="eyebrow">Project source</p><h1>Preparing the<br>next checkpoint.</h1><p>The public GitHub release is in preparation. The source repository is private while the initial release is assembled and reviewed.</p></section><section class="wrap narrow section"><div class="release-status"><span class="status-dot" aria-hidden="true"></span><div><strong>Public source: not available yet</strong><p>A direct GitHub link will appear here when the public repository is ready.</p></div></div><h2>What to expect here</h2><p>When the source release is ready, this page will point to the public repository, its license, versioned setup instructions, and contribution guidance. No release date is promised.</p><h2>Explore the project now</h2><p>The documentation covers the support workflow, the technician experience, and the architecture of a self-hosted deployment.</p><div class="actions"><a class="button primary" href="/docs/">Read the roadbook →</a><a class="text-link" href="/about/">About DeskRally ↗</a></div></section>''')
page('/privacy/','Website privacy','How this DeskRally project website handles visitor information.','''<section class="wrap page-head"><p class="eyebrow">Website information</p><h1>A small website.<br>A small footprint.</h1><p>This page describes the project website, not an organization’s DeskRally deployment.</p></section><section class="wrap narrow section"><h2>What the website does</h2><p>The site serves static pages, styles, scripts, and illustrations. Documentation search runs in your browser; search terms are not sent to a search service.</p><h2>What is not included</h2><p>This version has no analytics scripts, advertising, contact forms, account registration, embedded videos, third-party fonts, or application cookies. It does not ask for session codes or technician credentials.</p><h2>Hosting and access</h2><p>The hosting provider may process ordinary request information, such as an IP address and browser details, to deliver and protect the site. During private preview, the hosting platform may also require its own sign-in.</p><h2>Remote support is separate</h2><p>Accounts, support sessions, audit records, and remote-computer data belong to the deployment you use. Ask that deployment’s administrator about its handling of information.</p></section>''')
NAV=[('/docs/','Documentation'),('/about/','About'),('/source/','GitHub')]
def layout(path,entry):
 nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if path==href or href=='/docs/' and path.startswith('/docs/') else '')+f'>{name}</a>' for href,name in NAV)
 body=entry['body']
 if entry['kind']=='doc':
  side=''.join(f'<a href="/docs/{slug}/"'+(' aria-current="page"' if path==f'/docs/{slug}/' else '')+f'>{label}</a>' for slug,label,title,desc in DOCS)
  headings=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body)
  toc=''.join(f'<a href="#{anchor}">{title}</a>' for anchor,title in headings)
  body=f'<div class="wrap doc-layout"><aside class="doc-nav"><a class="doc-nav-home" href="/docs/">← All documentation</a><p class="eyebrow">Guides</p>{side}</aside><article class="article">{body}<div class="article-next"><a href="/docs/">← Back to the roadbook</a><a href="/docs/security/">Security & consent ↗</a></div></article><aside class="on-this-page"><p class="eyebrow">On this page</p>{toc}</aside></div>'
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(entry['description'],quote=True)}"><meta name="theme-color" content="#13283e"><meta name="robots" content="noindex,nofollow"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'self'; script-src 'self'; img-src 'self'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'"><meta property="og:title" content="{html.escape(entry['title'],quote=True)} · DeskRally"><meta property="og:description" content="{html.escape(entry['description'],quote=True)}"><meta property="og:type" content="website"><title>{entry['title']} · DeskRally</title><link rel="icon" type="image/svg+xml" href="/assets/rally-mark.svg"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/site.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav-inner"><a class="wordmark" href="/" aria-label="DeskRally home"><img src="/assets/rally-mark.svg" alt="" width="34" height="34">DeskRally</a><nav aria-label="Main navigation">{nav}</nav><a class="nav-start" href="/docs/getting-started/">Start here <span aria-hidden="true">↗</span></a></div></header><main id="main">{body}</main><footer class="site-footer"><div class="wrap footer-inner"><div><a class="wordmark" href="/"><img src="/assets/rally-mark.svg" alt="" width="28" height="28">DeskRally</a><p>Remote support. A clearer route.</p></div><nav aria-label="Footer navigation"><a href="/docs/">Documentation</a><a href="/about/">About</a><a href="/source/">Source release</a><a href="/privacy/">Website privacy</a></nav><span class="footer-stamp" aria-hidden="true">DR / KEEP MOVING<br><span class="checkers"></span></span></div></footer></body></html>'''
OUT.mkdir(exist_ok=True)
(OUT/'assets').mkdir(parents=True,exist_ok=True)
for path,entry in PAGES.items():
 dest=OUT/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(layout(path,entry),encoding='utf8',newline='\n')
for p in (ROOT/'assets').iterdir():
 if p.is_file():shutil.copy2(p,OUT/'assets'/p.name)
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n',encoding='utf8')
index=[{'path':path,'title':entry['title'],'text':html.unescape(re.sub('<[^>]+>',' ',entry['body']))} for path,entry in PAGES.items() if path.startswith('/docs/') and path!='/docs/']
js='''"use strict";
const guides=GUIDE_DATA;
const input=document.querySelector("#docs-search");
if(input){const cards=[...document.querySelectorAll("#guide-results .doc-card")];const count=document.querySelector("#search-count");const empty=document.querySelector("#search-empty");input.addEventListener("input",()=>{const words=input.value.toLocaleLowerCase().trim().split(/\\s+/).filter(Boolean);let visible=0;for(const card of cards){const item=guides.find(g=>g.path===card.getAttribute("href"));const match=words.every(w=>(item.title+" "+item.text).toLocaleLowerCase().includes(w));card.hidden=!match;if(match)visible++;}count.textContent=visible+" guide"+(visible===1?"":"s")+" found.";empty.hidden=visible!==0;});}
'''.replace('GUIDE_DATA',json.dumps(index,ensure_ascii=False))
(OUT/'assets/site.js').write_text(js,encoding='utf8',newline='\n')
print(json.dumps({'pages':len(PAGES),'docs':len(index),'output':'dist','external_runtime_dependencies':0}))
